import { useEffect, useState } from "react";
import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchCommits,
  uploadFile,
  fetchLiveCommits,
  fetchPRHeatmap,
  fetchMergeHeatmap
} from "./api/githubApi";

import MonthYearPicker from "./components/MonthYearPicker";

function App() {

  // ✅ STATES
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  const [commitHeatmap, setCommitHeatmap] = useState({});
  const [prHeatmap, setPrHeatmap] = useState({});
  const [mergeHeatmap, setMergeHeatmap] = useState({});
  const [liveCommits, setLiveCommits] = useState([]);

  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [userCreatedAt, setUserCreatedAt] = useState(null);

  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadMessage, setUploadMessage] = useState("Upload via dashboard");

  const [actionType, setActionType] = useState("commits");
  const [darkMode, setDarkMode] = useState(true);

  // ✅ FULL SCREEN DARK MODE
  useEffect(() => {
    document.body.style.margin = "0";
    document.body.style.backgroundColor = darkMode ? "#0F172A" : "#F8FAFC";
    document.body.style.color = darkMode ? "#F8FAFC" : "#0F172A";
  }, [darkMode]);

  // ✅ TOKEN
  useEffect(() => {
    const token = new URLSearchParams(window.location.search).get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // ✅ LOAD USER + REPOS
  useEffect(() => {
    if (!localStorage.getItem("token")) return;

    fetchLoggedUser().then(res => {
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  // ✅ LIVE COMMITS AUTO REFRESH
  // useEffect(() => {
  //   if (!owner || !selectedRepo) return;

  //   fetchLiveFeed();
  //   const interval = setInterval(fetchLiveFeed, 10000);
  //   return () => clearInterval(interval);

  // }, [owner, selectedRepo]);

  // const fetchLiveFeed = async () => {
  //   const res = await fetchLiveCommits({ owner, repo: selectedRepo });
  //   setLiveCommits(res.data || []);
  // };

  // ✅ HEATMAP BUILDERS
  const buildCommitHeatmap = async (payload) => {
    const res = await fetchCommits(payload);
    const map = {};
    res.data.forEach(c => {
      const d = c.commit.committer.date.substring(0, 10);
      map[d] = (map[d] || 0) + 1;
    });
    setCommitHeatmap(map);
  };

  const buildPRHeatmap = async (payload) => {
    const res = await fetchPRHeatmap(payload);
    setPrHeatmap(res.data);
  };

  const buildMergeHeatmap = async (payload) => {
    const res = await fetchMergeHeatmap(payload);
    setMergeHeatmap(res.data);
  };

  // ✅ ANALYZE
  const fetchData = async () => {
    const payload = { owner, repo: selectedRepo, startDate, endDate };

    if (actionType === "commits") await buildCommitHeatmap(payload);
    if (actionType === "prs") await buildPRHeatmap(payload);
    if (actionType === "merge") await buildMergeHeatmap(payload);
    if (actionType === "clone") {
      window.open(`https://github.com/${owner}/${selectedRepo}.git`, "_blank");
    }
  };

  // ✅ UPLOAD
  const handleUpload = async () => {
    if (!selectedFile) return alert("Select file");

    const reader = new FileReader();
    reader.onload = async () => {
      await uploadFile({
        owner,
        repo: selectedRepo,
        path: "uploads/" + selectedFile.name,
        content: reader.result.split(",")[1],
        message: uploadMessage
      });

      alert("✅ Uploaded");
      fetchData();
    };

    reader.readAsDataURL(selectedFile);
  };

  // ✅ RENDER HEATMAP
  const renderHeatmap = () => {
  const data =
    actionType === "commits" ? commitHeatmap :
    actionType === "prs" ? prHeatmap :
    actionType === "merge" ? mergeHeatmap :
    {};

  const days = Object.keys(data).sort();

  return (
    <div>
      <div className="heatmap-grid">
        {days.map(date => {
          const level = data[date] || 0;
          const intensity = Math.min(level, 4);

          return (
            <div
              key={date}
              className={`heat-box level-${intensity}`}
            >
              <span className="tooltip">
                {date} : {level}
              </span>
            </div>
          );
        })}
      </div>

      {/* ✅ LEGEND */}
      <div className="heatmap-legend">
        <span>Low</span>
        <div className="heat-box level-0"></div>
        <div className="heat-box level-1"></div>
        <div className="heat-box level-2"></div>
        <div className="heat-box level-3"></div>
        <div className="heat-box level-4"></div>
        <span>High</span>
      </div>
    </div>
  );
};

  // ✅ UI
  return (
    <div style={styles.container}>

      <div style={styles.topBar}>
        <h2>GitHub Analytics</h2>
        <button onClick={() => setDarkMode(!darkMode)}>
          {darkMode ? "☀ Light" : "🌙 Dark"}
        </button>
      </div>

      {!owner && (
        <button onClick={() => window.location.href =
          "http://localhost:8080/auth/github"}>
          Login with GitHub
        </button>
      )}

      {owner && (
        <>
          <div style={styles.form}>
            <select onChange={e => setSelectedRepo(e.target.value)}>
              {repos.map(repo => (
                <option key={repo.id} value={repo.name}>{repo.name}</option>
              ))}
            </select>

            <MonthYearPicker
              userCreatedAt={userCreatedAt}
              onChange={({ startDate, endDate }) => {
                setStartDate(startDate);
                setEndDate(endDate);
              }}
            />

            <select onChange={e => setActionType(e.target.value)}>
              <option value="commits">Commits</option>
              <option value="prs">Pull Requests</option>
              <option value="merge">Merged PRs</option>
              <option value="clone">Clone Repo</option>
            </select>

            <button onClick={fetchData}>Analyze</button>
          </div>

          <div style={styles.heatmapBox}>
            <div style={styles.topRightUpload}>
              <input type="file" onChange={e => setSelectedFile(e.target.files[0])} />
              <button onClick={handleUpload}>Upload</button>
            </div>

            <h3>Heatmap</h3>
            {renderHeatmap()}
          </div>

          {/* <div style={styles.liveBox}>
            <h3>🔴 Live Commits</h3>
            {liveCommits.map(c => (
              <div key={c.sha} style={styles.commitItem}>
                <b>{c.commit.message}</b><br/>
                <small>{c.commit.author.name}</small>
              </div>
            ))}
          </div> */}
        </>
      )}

      <style>{`
        .heatmap-grid {
          display: grid;
          grid-template-columns: repeat(53, 12px);
          gap: 4px;
          justify-content: center;
          margin-top: 15px;
        }
        .heat-box { width: 12px; height: 12px; border-radius: 2px; background: #1f2933; }
        .level-1 { background: #bbf7d0; }
        .level-2 { background: #4ade80; }
        .level-3 { background: #16a34a; }
        .level-4 { background: #166534; }
      `}</style>

    </div>
  );
}

const styles = {
  container: { minHeight: "100vh", padding: 20, fontFamily: "Arial" },
  topBar: { display: "flex", justifyContent: "space-between" },
  form: { display: "flex", gap: 10, justifyContent: "center", marginTop: 20 },
  heatmapBox: { width: "75%", margin: "30px auto", padding: 20, borderRadius: 12, background: "rgba(255,255,255,0.08)", position: "relative" },
  topRightUpload: { position: "absolute", right: 10, top: 10, display: "flex", gap: 6 },
  liveBox: { width: "75%", margin: "40px auto", padding: 20, background: "#020617", borderRadius: 12 },
  commitItem: { padding: 8, borderBottom: "1px solid #334155" }
};

export default App;
